import {profiles,obstacles,beacons,createState,step,sense} from './sim.js';
const $=id=>document.getElementById(id);let s=createState(),sensor='tof',noise=1,history=[],record=[],last=0,acc=0;const keys=new Set();let pointer={forward:0,turn:0};
function log(msg){const li=document.createElement('li');li.innerHTML=`<time>${s.time.toFixed(1)}s</time> / `;li.append(document.createTextNode(msg));$('log').prepend(li);while($('log').children.length>20)$('log').lastChild.remove();}
for(const [key,p]of Object.entries(profiles)){const b=document.createElement('button');b.innerHTML=`<span>${{tof:'◉',lidar:'◎',ultrasonic:')))',camera:'▣'}[key]}</span><div>${p.name}<small>${key==='lidar'?'Barrido completo':'Campo de visión limitado'}</small></div>`;b.onclick=()=>{sensor=key;sync();log('Sensor: '+p.name)};b.dataset.sensor=key;$('sensors').append(b)}
function sync(){document.querySelectorAll('[data-sensor]').forEach(b=>b.classList.toggle('active',b.dataset.sensor===sensor));$('range').textContent=profiles[sensor].range.toFixed(1)+' m';$('sensorTag').textContent=profiles[sensor].name.toUpperCase();}sync();
$('noise').oninput=e=>{noise=+e.target.value;$('noiseValue').textContent=noise+'×'};
$('arm').onclick=()=>{if(s.state==='DISARMED'){s.state='BALANCING';s.stop=false;log('Misión iniciada')}else log('Reinicia para rearmar')};$('stop').onclick=()=>{s.stop=true;s.state='FAULT';keys.clear();pointer={forward:0,turn:0};log('Paro virtual activado')};$('reset').onclick=()=>{s=createState();history=[];record=[];keys.clear();pointer={forward:0,turn:0};$('link').textContent='◉ Enlace virtual: conectado';log('Sistema reiniciado')};$('link').onclick=()=>{s.link=!s.link;$('link').textContent=s.link?'◉ Enlace virtual: conectado':'○ Enlace virtual: perdido';log(s.link?'Enlace recuperado':'Enlace perdido · consigna cero')};$('push').onclick=()=>{if(!['BALANCING','TELEOP'].includes(s.state))return log('Inicia la misión para perturbar');s.rate+=1.8;log('Perturbación angular aplicada')};
$('theme').onchange=e=>{document.body.dataset.theme=e.target.value;try{localStorage.setItem('sentinel-theme',e.target.value)}catch{}};try{const t=localStorage.getItem('sentinel-theme');if(['dark','silver','purple','ocean','sunset','rose','twilight'].includes(t)){$('theme').value=t;document.body.dataset.theme=t}}catch{}
addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());if(e.code==='Space')$('stop').click()});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>{keys.clear();pointer={forward:0,turn:0}});document.addEventListener('visibilitychange',()=>{keys.clear();pointer={forward:0,turn:0};last=0;acc=0});
for(const b of document.querySelectorAll('.pad button')){b.onpointerdown=e=>{b.setPointerCapture(e.pointerId);pointer={forward:+b.dataset.f||0,turn:+b.dataset.t||0}};b.onpointerup=b.onpointercancel=()=>pointer={forward:0,turn:0};}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('export').onclick=()=>download('sentinel-session.json',JSON.stringify({simulation:true,model:'educational-2d-v0.2',sensor,noise,state:s,samples:record},null,2),'application/json');
function canvas(id){const c=$(id),r=c.getBoundingClientRect(),d=devicePixelRatio||1;if(c.width!==Math.round(r.width*d)||c.height!==Math.round(r.height*d)){c.width=Math.round(r.width*d);c.height=Math.round(r.height*d)}const ctx=c.getContext('2d');ctx.setTransform(d,0,0,d,0,0);return [ctx,r.width,r.height]}
function draw(rays){const [c,w,h]=canvas('arena'),css=getComputedStyle(document.body),color=k=>css.getPropertyValue(k).trim(),scale=Math.min((w-70)/12,(h-60)/12),ox=(w-12*scale)/2,oy=(h-12*scale)/2;c.clearRect(0,0,w,h);c.save();c.translate(ox,oy);c.strokeStyle=color('--grid');c.lineWidth=1;for(let i=0;i<=12;i++){c.beginPath();c.moveTo(i*scale,0);c.lineTo(i*scale,12*scale);c.moveTo(0,i*scale);c.lineTo(12*scale,i*scale);c.stroke()}
for(const o of obstacles){c.fillStyle=color('--panel');c.strokeStyle=color('--muted');c.beginPath();c.roundRect((o.x-o.r)*scale,(o.y-o.r)*scale,o.r*2*scale,o.r*2*scale,8);c.fill();c.stroke();c.fillStyle=color('--muted');c.font='9px monospace';c.fillText('BLOCK',o.x*scale-14,o.y*scale+3)}
for(let i=0;i<beacons.length;i++){const b=beacons[i],x=b.x*scale,y=b.y*scale;c.strokeStyle=s.visited.includes(i)?color('--accent'):color('--muted');c.save();c.translate(x,y);c.rotate(Math.PI/4);c.strokeRect(-8,-8,16,16);c.restore();c.fillStyle=color('--text');c.font='10px monospace';c.fillText('0'+(i+1),x+14,y+3)}
c.strokeStyle=color('--accent');c.globalAlpha=.45;c.beginPath();s.path.forEach((p,i)=>i?c.lineTo(p.x*scale,p.y*scale):c.moveTo(p.x*scale,p.y*scale));c.stroke();for(const r of rays){c.globalAlpha=.10;c.beginPath();c.moveTo(s.x*scale,s.y*scale);c.lineTo((s.x+Math.cos(r.a)*r.d)*scale,(s.y+Math.sin(r.a)*r.d)*scale);c.stroke();if(r.hit){c.globalAlpha=.8;c.fillStyle=color('--accent');c.fillRect((s.x+Math.cos(r.a)*r.d)*scale-1,(s.y+Math.sin(r.a)*r.d)*scale-1,3,3)}}c.globalAlpha=1;c.translate(s.x*scale,s.y*scale);c.rotate(s.a);c.shadowColor=color('--accent');c.shadowBlur=15;c.fillStyle=color('--accent');c.beginPath();c.roundRect(-11,-9,22,18,5);c.fill();c.shadowBlur=0;c.fillStyle=color('--inner');c.fillRect(-7,-13,12,4);c.fillRect(-7,9,12,4);c.beginPath();c.moveTo(14,0);c.lineTo(6,-4);c.lineTo(6,4);c.fill();c.restore();
const [q,cw,ch]=canvas('chart');q.clearRect(0,0,cw,ch);q.strokeStyle=color('--accent');q.beginPath();history.forEach((v,i)=>{const x=i/150*cw,y=ch/2-v*40;i?q.lineTo(x,y):q.moveTo(x,y)});q.stroke();}
function render(){const rays=sense(s,sensor,noise);draw(rays);$('status').textContent=s.state;$('pidSignal').textContent='θ̇ '+s.rate.toFixed(3)+' rad/s · ∫e '+s.integral.toFixed(3)+' · u '+s.control.toFixed(3);$('pitch').textContent=(s.pitch*180/Math.PI).toFixed(1);$('speed').textContent=s.v.toFixed(2);$('distance').textContent=Math.min(...rays.map(r=>r.d)).toFixed(2);$('battery').textContent=s.battery.toFixed(0);$('time').textContent=new Date(s.time*1000).toISOString().slice(14,19)+' · consumo sintético';$('score').textContent=String(s.score).padStart(3,'0');$('hits').textContent=s.hits;$('progress').style.width=s.visited.length/3*100+'%';$('beacons').innerHTML=beacons.map((_,i)=>`<div class="beacon ${s.visited.includes(i)?'done':''}"><span>◇ Baliza 0${i+1}</span><span>${s.visited.includes(i)?'✓ VISITADA':'+100'}</span></div>`).join('');$('missionStatus').textContent=s.visited.length===3?'Misión completada · exporta tu sesión':`${s.visited.length} / 3 balizas visitadas`;}
function frame(t){if(last)acc+=Math.min(.1,(t-last)/1000);last=t;while(acc>=.02){const before=s.visited.length;step(s,{forward:pad.forward+pointer.forward+(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0),pid:{kp:+$('kp').value,ki:+$('ki').value,kd:+$('kd').value},turn:pad.turn+pointer.turn+(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)},.02);if(s.visited.length>before)log('Baliza registrada · +100 puntos');acc-=.02;if(Math.floor(s.time*10)>record.length){record.push({t:s.time,x:s.x,y:s.y,pitch:s.pitch,v:s.v,state:s.state,sensor,noise});if(record.length>18000)record.shift();s.path.push({x:s.x,y:s.y});if(s.path.length>1000)s.path.shift();history.push(s.pitch);if(history.length>150)history.shift();}}render();requestAnimationFrame(frame)}log('Laboratorio listo · datos simulados');requestAnimationFrame(frame);
import {massBudget,plateSTL} from './workshop.js';
const fields=['width','depth','thickness','material','mass','height','plateHeight','target','ballastHeight'];
function workshop(){const n=Object.fromEntries(fields.map(k=>[k,+$(k).value]));const valid=fields.every(k=>$(k).checkValidity()&&$(k).value!=='');$('stl').disabled=!valid;if(!valid){$('massResult').textContent='Introduce valores dentro de los límites.';return;}const r=massBudget({...n,density:n.material});$('massResult').textContent=`Placa sólida: ${r.plate.toFixed(1)} g · Total sin contrapeso: ${r.total.toFixed(1)} g · Centro: ${r.com.toFixed(1)} mm sobre eje. `+(Number.isFinite(r.ballast)?`Contrapeso sugerido: ${r.ballast.toFixed(1)} g a ${n.ballastHeight} mm. Masa final: ${(r.total+r.ballast).toFixed(1)} g.`:'El objetivo no es alcanzable con un contrapeso en esa altura.');}
fields.forEach(k=>$(k).addEventListener('input',workshop));$('design').onchange=()=>{const [w,d]={compact:[180,140],explorer:[220,180],cargo:[260,220]}[$('design').value];$('width').value=w;$('depth').value=d;workshop()};$('stl').onclick=()=>download('sentinel-plate-mm.stl',plateSTL(+$('width').value,+$('depth').value,+$('thickness').value),'model/stl');for(const k of ['kp','ki','kd'])$(k).oninput=()=>$(k+'Value').textContent=$(k).value;workshop();
let pad={forward:0,turn:0};document.addEventListener('sentinel-gamepad',e=>{pad=e.detail;if(pad.stop&&!s.stop)$('stop').click()});

let ambientMoving=true;try{ambientMoving=localStorage.getItem('sentinel-motion')!=='paused'}catch{}
function ambient(){document.body.dataset.motion=ambientMoving?'flow':'paused';$('ambientMotion').setAttribute('aria-pressed',String(ambientMoving));$('ambientMotion').textContent=ambientMoving?'◌ Color en movimiento':'◌ Color en pausa';try{localStorage.setItem('sentinel-motion',ambientMoving?'flow':'paused')}catch{}}
$('ambientMotion').onclick=()=>{ambientMoving=!ambientMoving;ambient()};ambient();
